import work_tree
from collections import defaultdict, Counter

open_rows=[]
for t in work_tree.list_trees():
    for b in work_tree.list_tree_branches(t.tree_id):
        bst=str(getattr(b.status,'value',b.status) or '').lower()
        if bst in {'complete','archived'}:
            continue
        for tk in work_tree.list_branch_tasks(b.branch_id):
            tst=str(getattr(getattr(tk,'status',None),'value',getattr(tk,'status','')) or '').lower()
            if tst in {'complete','dropped'}:
                continue
            open_rows.append((b.branch_id,b.title,tk.task_id,tk.title,str(getattr(tk,'updated_at',''))))

print('total_open_tasks',len(open_rows))
print('branches_with_open_tasks',len({r[0] for r in open_rows}))

by_title=Counter(r[3] for r in open_rows)
print('top_open_task_titles')
for k,v in by_title.most_common(8):
    print(f'{v} | {k}')

by_branch=defaultdict(list)
for r in open_rows:
    by_branch[r[0]].append(r)

print('branches_with_multiple_open_tasks')
multi=[(bid,rows[0][1],len(rows)) for bid,rows in by_branch.items() if len(rows)>1]
if not multi:
    print('none')
else:
    for bid,btitle,cnt in sorted(multi,key=lambda x:x[2], reverse=True)[:25]:
        print(f'{cnt} | {bid} | {btitle}')

print('sample_open_rows')
for bid,btitle,tid,ttitle,upd in sorted(open_rows,key=lambda x:x[4], reverse=True)[:50]:
    print(f'{bid} | {tid} | {ttitle}')
